"""RoboPaint 字: camera-calibrated six lengthwise brush strokes. No reset.
All motion is issued through the documented Robot client and saved for the record.
"""
import sys,json,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output'); r=Robot();Q=[0,1,0,0]; Z=.0202

def now():return np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:14])
def send(a,note='motion',cams=['practice_cam'],fps=4):
 a=np.asarray(a); out=None
 for i in range(0,len(a),180):
  idx=len(list(ROOT.glob('action_*.npz')))
  np.savez(ROOT/f'action_{idx:03d}.npz',poses=a[i:i+180],dt=.05,note=note)
  out=r.submit('ee_pose',a[i:i+180],dt=.05,cameras=cams,video='frames',video_fps=fps,note=note)
  out.save(f'/app/runs/action_{idx:03d}')
  for c,img in out.last.items():Image.fromarray(img).save(ROOT/f'{c}.png')
  print(idx,note, 'tip',out.meta['proprio']['now'][7:10], 'plan',out.meta.get('plan'),flush=True)
 return out

def move(p,sec=1,hold=.25,note='travel',cams=['practice_cam']):
 start=now();target=np.r_[p,Q]; n=max(1,int(sec/.05))
 a=np.linspace(start,target,n+1)[1:];a=np.r_[a,np.repeat(target[None,:],int(hold/.05),axis=0)]
 return send(a,note,cams)
def dip():
 move([-.10,.18,.08],2,note='above ink')
 move([-.10,.18,.023],.7,hold=.5,note='dip ink')
 move([-.10,.18,.07],.7,note='lift from ink')
def park():return move([-.29,.0,.13],2,note='park',cams=['canvas_cam','practice_cam','scene_cam'])
if __name__=='__main__':
 if sys.argv[1]=='park':park()
 elif sys.argv[1]=='dip':dip()
